using HRIS.Api.Controllers; using HRIS.Api.DTOs.ServiceAward; using HRIS.Api.Exceptions; using HRIS.Api.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages;
namespace HRIS.Api.Pages.ServiceAwards; [Authorize(AuthenticationSchemes="Cookies")] public class IndexModel:PageModel { private readonly IServiceAwardService _service; public IndexModel(IServiceAwardService service)=>_service=service; public List<ServiceAwardResponseDto> Items{get;set;}=new(); public async Task OnGetAsync()=>Items=await _service.GetAsync(User.ToUserContext()); public async Task<IActionResult> OnPostStatusAsync(int id,string status){try{await _service.MarkStatusAsync(id,status,User.ToUserContext());TempData["Success"]="Status service award diperbarui.";}catch(Exception ex)when(ex is BadRequestException or ForbiddenException or NotFoundException){TempData["Error"]=ex.Message;}return RedirectToPage();} }
